<?php $root_dir="/data/data/com.termux/files/home/apache/files";if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_GET['ajax'])){header('Content-Type: application/json; charset=UTF-8');$raw_input=file_get_contents('php://input');$data=json_decode($raw_input,true);$search_query=isset($data['query'])?trim($data['query']):'';$results=[];if($search_query!==''){try{$directory=new RecursiveDirectoryIterator($root_dir,RecursiveDirectoryIterator::SKIP_DOTS);$iterator=new RecursiveIteratorIterator($directory,RecursiveIteratorIterator::SELF_FIRST);$lower_query=mb_strtolower($search_query,'UTF-8');foreach($iterator as $file){if($file->isDir()||!$file->isReadable())continue;$filepath=$file->getPathname();if(preg_match('/(\/\.git|[\/\\\\]cache[\/\\\\]|[\/\\\\]vendor[\/\\\\]|[\/\\\\]node_modules[\/\\\\]|[\/\\\\]storage[\/\\\\])/',$filepath)){continue;}$ext=strtolower(pathinfo($file->getFilename(),PATHINFO_EXTENSION));if(in_array($ext,['php','html','js','css','txt','md','json','yaml'])){$file_content=@file_get_contents($filepath);if($file_content===false)continue;if(!str_contains(mb_strtolower($file_content,'UTF-8'),$lower_query)){continue;}$file_lines=explode("\n",$file_content);foreach($file_lines as $line_num=>$line_content){if(str_contains(mb_strtolower($line_content,'UTF-8'),$lower_query)){$relative_path=str_replace($root_dir.'/','',$filepath);$results[]=['file'=>htmlspecialchars($relative_path),'line'=>$line_num+1,'content'=>htmlspecialchars(trim($line_content))];if(count($results)>300)break 2;}}}}}catch(Exception $e){}}echo json_encode(['status'=>'success','results'=>$results]);exit;}?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0,maximum-scale=1.0,user-scalable=no"><title>Server-Side Search</title><style>html,body{background:#ffffff;color:#1f2328;font-family:Arial,-apple-system,sans-serif!important;margin:0!important;padding:0!important;width:100vw;height:100vh;overflow:hidden;box-sizing:border-box;}.search-panel{width:100vw;height:100vh;background:#f6f8fa;padding:20px!important;box-sizing:border-box;display:flex;flex-direction:column;}h2{margin-top:0;color:#0969da;border-bottom:1px solid #d0d7de;padding-bottom:10px;font-size:22px;margin-bottom:15px;font-weight:bold;display:flex;align-items:center;gap:8px;}.md2-inline-svg{width:24px;height:24px;vertical-align:middle;display:inline-block;flex-shrink:0;}.radar-color{fill:#0969da;}.btn-icon-color{fill:#ffffff;}.file-icon-color{fill:#57606a;}.form-box{display:flex;gap:10px;margin-bottom:15px;align-items:center;}input[type="text"]{flex-grow:1;padding:12px;font-size:15px;font-family:Arial,sans-serif!important;border:1px solid #d0d7de;border-radius:6px;background:#ffffff;color:#1f2328;outline:none;box-sizing:border-box;}input[type="text"]:focus{border-color:#0969da;box-shadow:0 0 0 3px rgba(9,105,218,0.15);}.btn-search{background:#1f2328;color:#ffffff;border:1px solid rgba(27,31,36,0.15);padding:0 25px;font-size:14px;font-family:Arial,sans-serif!important;font-weight:bold;border-radius:6px;cursor:pointer;transition:0.1s;display:inline-flex;align-items:center;gap:6px;}.btn-search:hover{background:#24292f;}.results-box{background:#ffffff;border:1px solid #d0d7de;border-radius:6px;padding:15px;height:calc(100vh - 120px)!important;overflow-y:auto;box-sizing:border-box;}.result-item{padding:12px;border-bottom:1px solid #d0d7de;font-size:14px;}.result-item:last-child{border-bottom:none;}.file-header{display:flex;align-items:center;gap:6px;margin-bottom:4px;}.file-path{color:#0969da;font-weight:bold;text-decoration:none;}.file-path:hover{text-decoration:underline;}.line-num{color:#57606a;font-weight:bold;margin-right:10px;}.code-snippet{background:#f6f8fa;padding:8px;border-radius:4px;display:block;margin-top:5px;font-family:monospace;white-space:pre-wrap;overflow-x:auto;border:1px solid #d0d7de;box-sizing:border-box;}.notify{color:#57606a;font-style:italic;text-align:center;padding:20px;font-size:15px;}@keyframes spin{0%{transform:rotate(0deg);}100%{transform:rotate(360deg);}}@media(max-width:768px){.search-panel{padding:12px!important;}h2{font-size:18px;margin-bottom:10px;}.results-box{height:calc(100vh - 105px)!important;padding:10px;}input[type="text"]{font-size:14px;padding:10px;}.btn-search{padding:0 15px;font-size:13px;height:40px;}.result-item{padding:8px;font-size:13px;}}</style></head><body><div class="search-panel"><h2><svg class="md2-inline-svg radar-color" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2v1.93zm6.9-2.54c-.26-.81-1-1.39-1.9-1.39h-1v-3c0-.55-.45-1-1-1H8v-2h2c.55 0 1-.45 1-1V7h2c1.1 0 2-.9 2-2v-.41c2.93 1.19 5 4.06 5 7.41 0 2.08-.8 3.97-2.1 5.39z"/></svg><span>Server-Side Search</span></h2><div class="form-box"><input type="text" id="query-input" placeholder="Enter keyword (e.g. Bcrypt, album, css)..." required><button onclick="executeAjaxSearch()" class="btn-search" id="search-button"><svg class="md2-inline-svg btn-icon-color" style="width:16px;height:16px;" viewBox="0 0 24 24"><path d="M15.5 14h-.79l-.28-.27C15.41 12.59 16 11.11 16 9.5 16 5.91 13.09 3 9.5 3S3 5.91 3 9.5 5.91 16 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 4.99L20.49 19l-4.99-5zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14z"/></svg><span>Search</span></button></div><div class="results-box" id="results-container"><div class="notify">Enter your query above.</div></div></div><script>function executeAjaxSearch(){const queryInput=document.getElementById("query-input");const resultsContainer=document.getElementById("results-container");const searchBtn=document.getElementById("search-button");const query=queryInput.value.trim();if(query==="")return;searchBtn.disabled=true;searchBtn.innerHTML='<svg class="md2-inline-svg btn-icon-color" style="width:16px;height:16px;animation:spin 1s linear infinite;" viewBox="0 0 24 24"><path d="M12 4V2C6.48 2 2 6.48 2 12h2c0-4.41 3.59-8 8-8zm0 14c4.41 0 8-3.59 8-8h2c0 5.52-4.48 10-10 10v-2z"/></svg> <span>Searching...</span>';resultsContainer.innerHTML='<div class="notify">Searching... Please wait</div>';fetch(window.location.pathname+"?ajax=1",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({query:query})}).then(response=>{if(!response.ok)throw new Error('HTTP '+response.status);return response.json();}).then(data=>{searchBtn.disabled=false;searchBtn.innerHTML='<svg class="md2-inline-svg btn-icon-color" style="width:16px;height:16px;" viewBox="0 0 24 24"><path d="M15.5 14h-.79l-.28-.27C15.41 12.59 16 11.11 16 9.5 16 5.91 13.09 3 9.5 3S3 5.91 3 9.5 5.91 16 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 4.99L20.49 19l-4.99-5zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14z"/></svg><span>Search</span>';if(data.status==="success"){const results=data.results;if(results.length===0){resultsContainer.innerHTML='<div class="notify">No matches found.</div>';return;}let htmlOutput=`<div style="font-weight:bold;margin-bottom:11px;color:#1a7f37;">Matches found: ${results.length}</div>`;results.forEach(res=>{htmlOutput+=`<div class="result-item"><div class="file-header"><svg class="md2-inline-svg file-icon-color" style="width:18px;height:18px;" viewBox="0 0 24 24"><path d="M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8l-6-6zm2 16H8v-2h8v2zm0-4H8v-2h8v2zm-3-5V3.5L18.5 9H13z"/></svg><a href="/${res.file}" target="_blank" class="file-path">${res.file}</a></div><span class="line-num">[Line: ${res.line}]</span><span class="code-snippet">${res.content}</span></div>`;});resultsContainer.innerHTML=htmlOutput;}}).catch(error=>{searchBtn.disabled=false;searchBtn.innerHTML='<svg class="md2-inline-svg btn-icon-color" style="width:16px;height:16px;" viewBox="0 0 24 24"><path d="M15.5 14h-.79l-.28-.27C15.41 12.59 16 11.11 16 9.5 16 5.91 13.09 3 9.5 3S3 5.91 3 9.5 5.91 16 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 4.99L20.49 19l-4.99-5zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14z"/></svg><span>Search</span>';resultsContainer.innerHTML='<div class="notify" style="color:#cf222e;">Error: '+error.message+'</div>';});}document.getElementById("query-input").addEventListener("keydown",function(e){if(e.key==="Enter"){executeAjaxSearch();}});</script></body></html>
